suite('Errors', () => {
    $43();
    test('Get Error Message', function () {
        assert.strictEqual($4m('Foo Bar'), 'Foo Bar');
        assert.strictEqual($4m(new Error('Foo Bar')), 'Foo Bar');
        let error = new Error();
        error = new Error();
        error.detail = {};
        error.detail.exception = {};
        error.detail.exception.message = 'Foo Bar';
        assert.strictEqual($4m(error), 'Foo Bar');
        assert.strictEqual($4m(error, true), 'Foo Bar');
        assert($4m());
        assert($4m(null));
        assert($4m({}));
        try {
            throw new Error();
        }
        catch (error) {
            assert.strictEqual($4m(error), 'An unknown error occurred. Please consult the log for more details.');
            assert.ok($4m(error, true).length > 'An unknown error occurred. Please consult the log for more details.'.length);
        }
    });
});
